-- ============================================
-- LUMA — Thème 14 : LONG 3/3 x4 — Un imprévu majeur à résoudre entièrement en anglais
-- ============================================


update scenarios set content = '{"characters": {"other_driver": "l''autre conducteur", "dispatcher": "le répartiteur", "insurance_agent": "l''agent d''assurance", "officer": "l''officier de police"}, "start_node": "n1", "nodes": {"n1": {"speaker": "you_thought", "text": "(A car merges into your lane too quickly — a minor collision, both cars stop.)", "text_fr": "(Une voiture se rabat dans votre voie trop vite — une collision mineure, les deux voitures s''arrêtent.)", "choices": [{"text": "(Get out calmly to check the damage and the other driver.)", "text_fr": "(Sors calmement pour vérifier les dégâts et l''autre conducteur.)", "next": "n2"}]}, "n2": {"speaker": "other_driver", "text": "I''m so sorry, I didn''t see you there! Are you okay?", "text_fr": "Je suis vraiment désolé, je vous avais pas vu là ! Ça va ?", "choices": [{"text": "I''m fine, just a bit shaken. Let''s check the damage together.", "text_fr": "Ça va, un peu secoué juste. Vérifions les dégâts ensemble.", "next": "n3"}, {"text": "I''m okay. We should exchange insurance information right away.", "text_fr": "Ça va. On devrait échanger nos informations d''assurance tout de suite.", "next": "n3"}]}, "n3": {"speaker": "other_driver", "text": "You''re right, let me grab my insurance card from the glove compartment.", "text_fr": "T''as raison, laisse-moi prendre ma carte d''assurance dans la boîte à gants.", "choices": [{"text": "(Take photos of both cars and the scene while waiting.)", "text_fr": "(Prends des photos des deux voitures et de la scène en attendant.)", "next": "n4"}]}, "n4": {"speaker": "other_driver", "text": "Here''s my information. This is honestly my first accident, I''m a bit rattled.", "text_fr": "Voici mes informations. C''est honnêtement mon premier accident, je suis un peu secoué.", "choices": [{"text": "It''s okay, these things happen. Let''s just handle this calmly together.", "text_fr": "C''est bon, ça arrive. Gérons juste ça calmement ensemble.", "next": "n5"}, {"text": "I understand, accidents are stressful. Should we call the police to file a report?", "text_fr": "Je comprends, les accidents sont stressants. On devrait appeler la police pour faire un rapport ?", "next": "n5"}]}, "n5": {"speaker": "other_driver", "text": "Probably a good idea, just to have it documented properly.", "text_fr": "Probablement une bonne idée, juste pour que ce soit bien documenté.", "choices": [{"text": "(Call the police non-emergency line to report the accident.)", "text_fr": "(Appelle la ligne non urgente de la police pour signaler l''accident.)", "next": "n6"}]}, "n6": {"speaker": "dispatcher", "text": "We''ll send an officer to your location. Please stay safe until they arrive.", "text_fr": "On va envoyer un officier à votre position. Restez en sécurité jusqu''à son arrivée.", "choices": [{"text": "Thank you, we''ll wait here safely.", "text_fr": "Merci, on va attendre ici en sécurité.", "next": "n7"}]}, "n7": {"speaker": "you_thought", "text": "(While waiting, you call your insurance company to report the incident.)", "text_fr": "(En attendant, vous appelez votre compagnie d''assurance pour signaler l''incident.)", "choices": [{"text": "(Explain the situation clearly and calmly to the insurance agent.)", "text_fr": "(Explique la situation clairement et calmement à l''agent d''assurance.)", "next": "n8"}]}, "n8": {"speaker": "insurance_agent", "text": "Thank you for the details. We''ll start processing your claim right away.", "text_fr": "Merci pour les détails. On va commencer à traiter votre réclamation tout de suite.", "choices": [{"text": "What should I expect for next steps after this?", "text_fr": "Je devrais m''attendre à quoi comme prochaines étapes après ça ?", "next": "n9"}]}, "n9": {"speaker": "insurance_agent", "text": "We''ll contact the other party''s insurance, and you''ll get an update within 48 hours.", "text_fr": "On va contacter l''assurance de l''autre partie, et vous aurez une mise à jour d''ici 48 heures.", "choices": [{"text": "Perfect, thank you for walking me through this.", "text_fr": "Parfait, merci de m''avoir guidé à travers ça.", "next": "n10"}]}, "n10": {"speaker": "officer", "text": "(Arrives) Alright, let''s get a report started. Can you walk me through what happened?", "text_fr": "(Arrive) Bon, commençons un rapport. Vous pouvez me raconter ce qui s''est passé ?", "choices": [{"text": "(Calmly explain the sequence of events to the officer.)", "text_fr": "(Explique calmement la séquence des événements à l''officier.)", "next": "n11"}]}, "n11": {"speaker": "officer", "text": "Thank you, that matches the other driver''s account too. This looks straightforward.", "text_fr": "Merci, ça correspond aussi au récit de l''autre conducteur. Ça semble simple.", "choices": [{"text": "That''s a relief. What happens now with the report?", "text_fr": "Ça soulage. Qu''est-ce qui se passe maintenant avec le rapport ?", "next": "n12"}]}, "n12": {"speaker": "officer", "text": "I''ll file this today, you''ll get a copy for your insurance within a few days.", "text_fr": "Je vais déposer ça aujourd''hui, vous aurez une copie pour votre assurance d''ici quelques jours.", "choices": [{"text": "Thank you, officer. I appreciate you handling this so smoothly.", "text_fr": "Merci, officier. J''apprécie que vous ayez géré ça sans problème.", "next": "n13"}]}, "n13": {"speaker": "other_driver", "text": "Thank you for being so calm through all this. It really helped me stay collected too.", "text_fr": "Merci d''être resté si calme à travers tout ça. Ça m''a vraiment aidé à rester posé aussi.", "choices": [{"text": "We handled it as a team, honestly. Glad no one was hurt.", "text_fr": "On l''a géré en équipe, honnêtement. Content que personne n''ait été blessé.", "next": "end_resolved"}]}, "end_resolved": {"speaker": "other_driver", "text": "Agreed. Drive safe the rest of your trip, and again, I''m really sorry.", "text_fr": "D''accord. Conduisez prudemment pour le reste de votre voyage, et encore, je suis vraiment désolé.", "end": true, "ending_label": "Accident géré de bout en bout avec calme et méthode 🚗📋✅"}}}'::jsonb, is_playable = true
where title = 'Un imprévu majeur à résoudre entièrement en anglais'
  and theme_id = (select id from scenario_themes where position = 14 and language_id = (select id from languages where code = 'en'));
